handleStatsMore() {
  // 在市场监测大屏进入前（用户点击手势中）请求浏览器全屏，使其默认全屏展示；
  // 若浏览器不支持或用户拒绝，则直接进入（页面本身已铺满视口）。
  const nav = () => this.$router.push('/market-monitor').catch(() => {})
  const el = document.documentElement
  if (!document.fullscreenElement && el.requestFullscreen) {
    el.requestFullscreen().then(nav).catch(nav)
  } else {
    nav()
  }
}

tool_input.new_string:
handleStatsMore() {
  // 先跳转到市场监测大屏，再进入浏览器全屏。
  // 注意：requestFullscreen 必须在同步的点击手势内调用，否则会被浏览器拦截，
  // 因此这里先触发路由跳转（同步开始导航），紧接着在同一手势内请求全屏，
  // 避免出现"先全屏、页面还停在首页"的观感。
  const el = document.documentElement
  const navPromise = this.$router.push('/market-monitor').catch(() => {})
  if (!document.fullscreenElement && el.requestFullscreen) {
    el.requestFullscreen().catch(() => {})
  }
  return navPromise
}

